import{_ as o,l as n,o as t,c as l,v as e,p as s,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"波动性中断与再开盘","description":"","frontmatter":{"title":"波动性中断与再开盘","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/volatility-auction.md","filePath":"quant/volatility-auction.md","lastUpdated":1789023840000}'),E={name:"quant/volatility-auction.md"};function c(A,a,u,m,_,B){const r=n("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="波动性中断与再开盘" tabindex="-1">波动性中断与再开盘 <a class="header-anchor" href="#波动性中断与再开盘" aria-label="Permalink to &quot;波动性中断与再开盘&quot;">​</a></h1><div class="epigraph"><p>交易暂停把连续匹配关掉，不是把价格发现关掉；再开盘集合要在一段极端到达之后重新找到可交易价格，而日历上的开盘并没有这段刚刚中断的连续历史。</p><footer>—— 据 Christie, Corwin and Harris 对 NASDAQ 交易暂停的研究；对照 SEC Limit Up–Limit Down 与各交易所波动性中断规则</footer></div><p><a href="/quant/opening-closing-call">开盘与收盘集合竞价</a>给出了日历上预先安排的两场拍卖。本课的缺口是<strong>状态触发</strong>的暂停：价格相对参考价移动过快、触及静态或动态阈值，连续协议被强制换成集合协议，然后再开盘。Christie、Corwin 与 Harris 表明，暂停之后的恢复质量取决于暂停期间信息是否仍在别处交易、以及再开盘如何组织。LULD、欧洲的波动中断、A 股的临时停牌与盘中临停，同属这一族，参数不同。本课不重讲批量出清公式，只补：触发、冻结、再开盘与连续段重启。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续段的价差会计假定匹配一直开着。极端到达时，做市商撤出、深度空洞、市价沿空簿扫出离谱成交。监管与交易所用波动性中断（volatility interruption / auction halt）把时钟切成：触发 → 暂停/累积 → 再开盘出清 → 恢复连续。问题是这把刀切在哪。阈值太宽，等于没有保护；太窄，正常的跳价也会把股票反复送进拍卖，流动性被制度本身切断。参考价用谁——前一次拍卖价、一段时间的成交均价、还是指数挂钩的参考带——决定「波动」测量的是个股跳跃还是共同冲击。</p><p>与涨跌停的差别必须写清。涨跌停是价格栅格的硬边界，匹配可以继续，只是一侧没有对手价。波动中断是<strong>停止匹配</strong>一段时间。A 股涨跌停与临停并存：停板时连续仍可能排队，临停则进入停牌状态。把 LULD 的经验数字直接当成涨跌停的成本，对象错了。</p><h3 id="暂停期间信息在哪交易" tabindex="-1">暂停期间信息在哪交易 <a class="header-anchor" href="#暂停期间信息在哪交易" aria-label="Permalink to &quot;暂停期间信息在哪交易&quot;">​</a></h3><p>若同一证券在期货、ETF、暗池或海外上市处仍在交易，暂停只关掉了一张簿，没有关掉价格发现。再开盘时，公开股票簿必须一次性吸收别处已经写出的价格，跳价会显得「拍卖很差」，其实是连续段被关掉的后果。Christie–Corwin–Harris 对 NASDAQ 暂停的讨论，核心就是暂停是否伴随信息继续流动。单市场、单上市的股票，暂停更接近真正的信息真空，再开盘更像一次小型开盘。</p><p><span class="marginnote">参考价若用「最后一笔连续成交」，而最后一笔已是扫空簿的离谱打印，中断会被自己的错价触发。规则通常用一段时间的参考价或排除异常打印。研究样本必须用交易所定义的参考价，不能自己用最后成交重算阈值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件研究以触发时刻 \\(t_0\\) 为原点。记录：触发前 \\(k\\) 秒的深度与价差、触发原因（静态带 / 动态带 / 监管停牌）、暂停时长、再开盘是否延长、出清价相对触发前中点与相对参考价的位置、再开盘量、恢复连续后价差与深度回到中位的时间。对照组用未触发但收益同样大的日子，否则会把「大新闻」与「中断制度」混在一起。</p><p>再开盘集合沿用先修课的出清语言：最大成交量、剩余处理、是否披露虚拟价。与日历开盘的差别应单独成列：开盘前有隔夜订单簿的累积；波动中断前有刚刚还在报价的做市商，他们可能已经撤光。恢复连续后第一批报价的宽度，是存货与逆向选择在极端事件后的重新开张，不要并入全日平均价差。</p><h3 id="阈值、延长与「再次中断」" tabindex="-1">阈值、延长与「再次中断」 <a class="header-anchor" href="#阈值、延长与「再次中断」" aria-label="Permalink to &quot;阈值、延长与「再次中断」&quot;">​</a></h3><p>动态阈值随近期价格移动，静态阈值相对前收或前一次拍卖。两者同时存在时，慢牛可以用完静态带而不触发动态带，闪崩则先撞动态带。再开盘若仍无法在阈值内出清，规则允许延长累积或再次中断。样本里「一次中断」可能是一串中断，统计上应把串当成一个事件，否则暂停次数被制度的递归放大。执行算法必须把中断写成状态机：暂停期能否改单、再开盘是否自动转入、失败后订单是过期还是留到连续。回测若在中断期仍按历史成交价给你成交，是在虚构对手盘。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中断的直接机制是停止错误价格上的匹配，让买卖双方在集合里重新显示需求。间接机制是协调：所有人知道暂时不能成交，抢跑连续簿的价值下降，但抢虚拟参考价的价值上升。若再开盘披露不平衡，博弈类似收盘拍卖；若不披露且时长很短，更像蒙眼批量。做市商在触发前的撤单，使中断看起来像「流动性消失」；中断本身又使流动性合法地消失一段时间。要把这两种消失分开：前者是代理人选择，后者是规则。</p><p>对价格发现：中断推迟了连续写入，把一段信息压进再开盘跳价。若信息是共同的（指数闪崩），个股再开盘应对齐期货与 ETF；若信息是个股的（公告误发、乌龙指），再开盘应对齐公告文本的时间戳。把所有再开盘跳价都叫「发现价值」，会把乌龙指的回吐也算进 alpha。</p><p><span class="marginnote"><a href="/quant/kyle-model">Kyle</a> 的批量拍卖没有「先连续再强制改集合」这一段历史。波动中断的 \\(\\lambda\\) 若用中断窗口的收益对成交量来估，分母接近零、分子是跳价，数字会爆炸。应把中断事件从连续 lambda 样本里剔除，单独报告。</span></p>',18)),(t(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%BF%9E%E7%BB%AD%E5%8C%B9%E9%85%8D%22%5D%20--%3E%20T%5B%22%E8%A7%A6%E5%8F%8A%E9%9D%99%E6%80%81%E6%88%96%E5%8A%A8%E6%80%81%E9%98%88%E5%80%BC%22%5D%0A%20%20T%20--%3E%20H%5B%22%E6%9A%82%E5%81%9C%E5%B9%B6%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20H%20--%3E%20A%5B%22%E5%86%8D%E5%BC%80%E7%9B%98%E9%9B%86%E5%90%88%E5%87%BA%E6%B8%85%22%5D%0A%20%20A%20--%3E%20R%5B%22%E6%81%A2%E5%A4%8D%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20A%20--%3E%20E%5B%22%E5%BB%B6%E9%95%BF%E6%88%96%E5%86%8D%E6%AC%A1%E4%B8%AD%E6%96%AD%22%5D%0A%20%20E%20--%3E%20H%0A%20%20R%20--%3E%20C%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="乌龙指与公告停牌不要进同一事件样本" tabindex="-1">乌龙指与公告停牌不要进同一事件样本 <a class="header-anchor" href="#乌龙指与公告停牌不要进同一事件样本" aria-label="Permalink to &quot;乌龙指与公告停牌不要进同一事件样本&quot;">​</a></h3><p>价格路径触发的中断与待披露公告的监管停牌，外形都是暂停再开盘，信息集完全不同。混样会把「规则切断匹配」与「公司即将说话」估成同一个再开盘质量。事件表必须用交易所原因码，不能只用收益率阈值。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>监管停牌（待披露公告）与波动中断外形相似，信息集不同：前者常伴随即将发布的公司信息，后者常伴随已经发生的价格路径。不要合并样本。跨上市股票在一处中断、别处仍开，套利约束决定再开盘价，个股拍卖质量不能当单市场实验。加密永续的标记价格与分档强平是另一套中断，见<a href="/quant/crypto-mark-price">标记价格</a>，不要把 LULD 的阈值语言套过去。</p><p>本课不提供如何在中断边界上下单以获取优先成交的操作说明。研究问题是制度如何改变连续价差会计的样本：哪些分钟必须从有效价差均值里拿掉，哪些再开盘必须当集合事件。</p><p><span class="marginnote">A 股盘中临停、临时停牌与涨跌停是三条规则。临停有时长与复牌集合；涨跌停不一定停牌。写代码时用交易所状态字段，不要用「收益率超过 10%」当停牌代理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>波动中断把连续协议暂时换成集合协议，触发是状态依赖的，不是日历。</li><li>与涨跌停不同：中断停止匹配；停板仍可能排队。</li><li>再开盘质量取决于暂停期信息是否在别处交易，以及披露与延长规则。</li><li>事件研究要对照「同样大的未中断日」，并把连续中断串当成一个事件。</li><li>连续 lambda 与全日价差均值必须剔除中断窗口。</li><li>出处：Christie, Corwin and Harris, <em>Journal of Financial Economics</em>, 2002；Corwin and Lipson 对纽约暂停的相关工作；LULD 与各交易所公开的波动性中断规则。</li></ul>',8))])}const q=o(E,[["render",c]]);export{D as __pageData,q as default};
